pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess) public {
        // Ensure the contract has enough balance for the reward
        vm.deal(address(c), 2 ether);
        // Player must have 1 ether to lock in a guess
        vm.deal(msg.sender, 1 ether);

        // Player locks in a guess
        vm.prank(msg.sender);
        c.lockInGuess{value: 1 ether}(guess);

        // Advance to the block where settle is valid (block.number > stored block)
        // The stored block is block.number + 1 at time of lockInGuess
        // We need to mine to at least that block + 1
        vm.roll(block.number + 3);

        // Player calls settle
        vm.prank(msg.sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("settle()"));

        // General rule: If settle did not revert, then either the guess was wrong or the contract had insufficient balance.
        // In the reference, if guess matches answer at block.number+1, settle succeeds and transfers 2 ether.
        // In the mutant, answer uses block.number-1 which is different, so the guess will never match, and settle will always succeed without transfer.
        // The invariant: After lockInGuess, calling settle can succeed (not revert) regardless of guess.
        assertTrue(success);
    }
}

