pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 hash) public {
        // Fund the contract with initial 1 ether
        vm.deal(address(c), 1 ether);

        // Fund the caller with enough ether
        vm.deal(address(this), 1 ether);

        // Call lockInGuess with the required 1 ether
        c.lockInGuess{value: 1 ether}(hash);

        // Advance to the next block so the lock-in block is in the past
        vm.roll(block.number + 2);

        // The reference contract: answer = keccak256(blockhash(guesses[msg.sender].block))
        // guesses[msg.sender].block = block.number + 1 (the block we just advanced past)
        // The blockhash of that block is known (zero in test environment before first block)
        // The mutant: answer = keccak256(blockhash(block.number - 1))
        // This will differ if the blockhash of (block.number - 1) differs from blockhash of the locked-in block

        // The general rule: In the reference, the answer uses the blockhash of the locked-in block,
        // which is deterministic (0) for a future block that hasn't been mined yet.
        // The mutant uses blockhash of the current block minus 1, which could be non-zero.
        // So the result of settle() will differ (revert vs success, or transfer amount differs).

        // We can only observe the result via revert or balance change.
        uint256 balanceBefore = address(c).balance;

        // Try settle; it may revert or succeed
        bool reverted = false;
        try c.settle() {
            // succeed
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;

        // The reference should settle without revert (if guess matches blockhash or not),
        // but the mutant may revert or produce different balance change.
        // Since we cannot read the guess or answer directly, we use the revert flag and balance.
        // For this test, the property is: In the reference, settle() always succeeds (no revert)
        // because we are at a block > locked-in block and the guess might match or not, but no revert.
        // The mutant may revert because its answer computation uses a different blockhash.
        // So the general rule: settle() does not revert in reference; mutant may revert.

        // Actually, we need a stronger general rule that holds for all fuzz inputs.
        // The difference: The reference computes answer from blockhash(guesses[msg.sender].block),
        // which is the blockhash of a future block at lock-in time. In the test environment,
        // blockhash() for a future block returns 0. So the reference answer = keccak256(abi.encodePacked(0)).
        // The mutant computes answer from blockhash(block.number - 1), which is the hash of the
        // previous block (non-zero if we have mined blocks). So if the guess equals keccak256(0),
        // the reference will transfer 2 ether, but the mutant will not because its answer is different.
        // Therefore, a general rule: if the guess equals keccak256(0), then after settle(),
        // the contract balance decreases by 2 ether in reference, but not in mutant.

        // Let's use this: if hash == keccak256(abi.encodePacked(bytes32(0))), then reference transfers.
        bytes32 zeroBlockHash = keccak256(abi.encodePacked(bytes32(0)));
        if (hash == zeroBlockHash) {
            // In the reference, settle should transfer 2 ether => balance decreases by 2
            // (assuming enough balance). The contract has 1 ether from constructor + 1 from lockInGuess = 2 ether.
            // After transfer of 2 ether, balance becomes 0.
            assertTrue(balanceAfter == balanceBefore - 2 ether, "Reference should transfer 2 ether when guess matches");
        } else {
            // Otherwise, no transfer, balance unchanged
            assertTrue(balanceAfter == balanceBefore, "Reference should not transfer when guess mismatches");
        }
    }
}

